// Generates typed views of contracts/ that openapi-typescript cannot express:
//  - src/api/events.gen.ts: the event union keyed by `type` (events.schema.json if/then branches)
//  - src/api/permissions.gen.ts: the permission catalog and built-in roles (permissions.yaml)
// Run with `pnpm generate:api`. Never edit the generated files by hand.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parse } from 'yaml'

const here = dirname(fileURLToPath(import.meta.url))
const contracts = resolve(here, '../../contracts')
const out = resolve(here, '../src/api')
const header = '// Generated by scripts/gen-contract-data.mjs from contracts/. Do not edit.\n'

// ---------------------------------------------------------------- events
const events = JSON.parse(readFileSync(resolve(contracts, 'events.schema.json'), 'utf8'))
const types = events.$defs.EventType.enum
const mapping = {}
for (const branch of events.allOf) {
  const type = branch.if.properties.type.const
  const ref = branch.then.properties.payload.$ref
  mapping[type] = ref.split('/').pop()
}
for (const t of types) {
  if (!mapping[t]) throw new Error(`event type ${t} has no payload schema`)
}
let ev = header
ev += "import type { components } from './schema.gen'\n\n"
ev += 'type S = components["schemas"]\n\n'
ev += `export const EVENT_TYPES = ${JSON.stringify(types)} as const\n`
ev += 'export type EventType = (typeof EVENT_TYPES)[number]\n\n'
ev += 'export interface EventPayloads {\n'
for (const t of types) ev += `  ${t}: S['${mapping[t]}']\n`
ev += '}\n\n'
ev += '/** Envelope fields of every event (events.schema.json). */\n'
ev += 'export interface EventEnvelope {\n'
ev += "  mission_id: S['Id']\n  job_id: S['Id'] | null\n  seq: number\n  ts: S['Timestamp']\n"
ev += '  agent?: string | null\n  step_id?: string | null\n}\n\n'
ev += '/** One mission event, discriminated by `type`. */\n'
ev +=
  'export type ZEvent = { [K in EventType]: EventEnvelope & { type: K; payload: EventPayloads[K] } }[EventType]\n'
ev += 'export type ZEventOf<K extends EventType> = Extract<ZEvent, { type: K }>\n\n'
ev += 'export function isEventType(value: string): value is EventType {\n'
ev += '  return (EVENT_TYPES as readonly string[]).includes(value)\n}\n'
writeFileSync(resolve(out, 'events.gen.ts'), ev)

// ---------------------------------------------------------------- permissions
const perms = parse(readFileSync(resolve(contracts, 'permissions.yaml'), 'utf8'))
const names = Object.keys(perms.permissions)
function expand(role, seen = new Set()) {
  if (seen.has(role)) return []
  seen.add(role)
  const items = perms.roles[role] ?? []
  const outp = new Set()
  for (const item of items) {
    if (item === '*') names.forEach((n) => outp.add(n))
    else if (perms.roles[item]) expand(item, seen).forEach((n) => outp.add(n))
    else outp.add(item)
  }
  return [...outp].sort()
}
let pm = header
pm += `export const PERMISSIONS = ${JSON.stringify(perms.permissions, null, 2)} as const\n\n`
pm += 'export type PermissionName = keyof typeof PERMISSIONS\n\n'
pm += `export const BUILTIN_ROLES = ${JSON.stringify(
  Object.fromEntries(Object.keys(perms.roles).map((r) => [r, expand(r)])),
  null,
  2,
)} as const\n\n`
pm += 'export type BuiltinRole = keyof typeof BUILTIN_ROLES\n\n'
pm += `export const LOCAL_ACCOUNT_LIMITS = ${JSON.stringify(perms.local_accounts, null, 2)} as const\n`
writeFileSync(resolve(out, 'permissions.gen.ts'), pm)

console.log(
  `events: ${types.length} types; permissions: ${names.length}, roles: ${Object.keys(perms.roles).length}`,
)
